const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const phases=[{name:'The Baseline Builder',headline:'Find your<br>bounce.',weeks:'WEEKS 1–2',duration:10,rounds:5,jump:20,rest:40,warm:'Jog in place for 1 minute, then hop softly without the rope for 1 minute.',milestone:'Consistently hit 15–20 consecutive jumps in your challenges.',challenge:'The Max Out Challenge',tip:'One attempt. Find out how many consecutive jumps you can do.',warmSteps:[['Jog in place','Light jogging. Get your body moving.',60],['Find a soft landing','Jump on the balls of your feet without the rope.',60]]},{name:'Building Momentum',headline:'Find your<br>flow.',weeks:'WEEKS 3–4',duration:12,rounds:6,jump:30,rest:30,warm:'Hop forward, backward, and sideways over a rope laid flat on the ground.',milestone:'Jump for most of each 30-second interval with no more than one trip.',challenge:'The Plus One Game',tip:'Aim for just one jump beyond your previous best. Small wins add up.',warmSteps:[['Coordination hops','Lay the rope flat. Hop forward, backward, and sideways over it.',120]]},{name:'The 50-Jump Club',headline:'Hello,<br>fifty.',weeks:'WEEKS 5+',duration:15,rounds:6,jump:40,rest:20,warm:'Dynamic stretches and light jumping to get ready.',milestone:'Reach 50 consecutive jumps. Welcome to the club!',challenge:'The 50-Jump Challenge',tip:'See if you can string together 50 consecutive jumps in one go.',warmSteps:[['Warm up your bounce','Do dynamic stretches and light jumping.',120]]}];
const jumpers=createJumperStore(localStorage);let data=jumpers.load();
function persist(){try{jumpers.save(data);return true;}catch(e){toast(e.message.includes('nickname')?e.message:'Could not save progress. Export a backup before leaving this page.');return false;}}
function renderJumperOptions(){const select=$('#jumper-select');select.replaceChildren();jumpers.list().forEach(p=>{const o=document.createElement('option');o.value=p.id;o.textContent=p.name;select.append(o);});select.value=jumpers.active();$('#settings').setAttribute('aria-label',`Your jumper: ${data.name}`);$('#current-jumper-name').textContent=data.name;$('.jumper-avatar').textContent=(data.name||'J')[0].toUpperCase();$('.profile-switch').hidden=jumpers.list().length<2;}
$('#jumper-select').onchange=e=>{if($('#session').open){e.target.value=jumpers.active();return;}if(!persist()){e.target.value=jumpers.active();return;}try{data=jumpers.switch(e.target.value);render();$('#name').value=data.name;$('#sound').checked=data.sound;toast(`Let’s go, ${data.name}!`);}catch{toast('Could not switch jumpers. Check browser storage.');renderJumperOptions();}};
$('#add-jumper').onclick=()=>{if($('#session').open)return;$('#profile').close();$('#new-jumper-name').value='';$('#jumper-error').textContent='';$('#new-jumper').showModal();$('#new-jumper-name').focus();};
$('#close-new-jumper').onclick=()=>$('#new-jumper').close();
$('#new-jumper-form').onsubmit=e=>{e.preventDefault();if(!persist())return;try{data=jumpers.add($('#new-jumper-name').value);$('#new-jumper').close();render();toast(`Welcome to Jump Club, ${data.name}!`);}catch(e){$('#jumper-error').textContent=e.message.includes('nickname')?e.message:'Could not save a new jumper. Check browser storage.';}};
function dayKey(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}function dateOf(k){return new Date(k+'T12:00:00')}function daysBetween(a,b){return Math.round((dateOf(a)-dateOf(b))/86400000)}function best(){return Math.max(0,...data.sessions.map(s=>s.jumps))}function streak(){return workoutStreak(data.sessions,dayKey()).count}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4000)}function safe(t){const n=document.createElement('span');n.textContent=t;return n.innerHTML}function show(view){$$('.view').forEach(v=>v.hidden=v.id!==view);$$('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===view))}$$('.nav').forEach(b=>b.onclick=()=>{show(b.dataset.view);render()});
function render(){renderJumperOptions();const p=phases[data.phase],b=best(),goal=nextMilestone(data.sessions);const milestoneBest=goal.type==='jumps'?b:Math.max(0,...data.sessions.filter(s=>s.phase===2).map(s=>s.seconds||0));$('#date').textContent=new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'});$('#phase-num').textContent=data.phase+1;$('#phase-weeks').textContent=p.weeks;$('#workout-title').innerHTML=p.headline;$('#duration').textContent=`◷  ~${p.duration} minutes`;$('#rounds').textContent=`↻  ${p.rounds} rounds`;$('#workout-sub').innerHTML=data.phase===0?'A little practice. A smoother rhythm.<br>Let’s build your jumping superpower.':data.phase===1?'One more jump. A little more confidence.<br>You’re finding your flow.':'Your next big adventure is here.<br>Let’s take it one jump at a time.';const dates=data.sessions.map(s=>s.date),today=dayKey();const schedule=workoutStreak(data.sessions,today);const gap=schedule.anchor?calendarDay(today)-calendarDay(schedule.anchor):null;$('#rest-note').textContent=gap===0?'Workout complete. Rest tomorrow; return the day after.':gap===1?'Rest day. Your next streak workout is tomorrow.':gap===2?'Workout due today. Keep your every-other-day streak alive.':gap>2?'A fresh start awaits. Jump today to begin a new streak.':'Every other day. Rest days count as growing days.';$('#start').textContent=dates.includes(today)?'Jump again ↗':'Let’s jump ↗';$('#streak').textContent=streak();$('#best').textContent=b;$('#goal-label').textContent=`Next little win: ${b+1} jump${b?'s':''}`;$('#goal-bar').style.width=Math.min(milestoneBest/goal.target*100,100)+'%';$('#goal-count').textContent=`${milestoneBest} / ${goal.target}`;$('#goal-unit').textContent=goal.type==='jumps'?'consecutive jumps':'seconds continuous';$('.club-bottom').firstChild.textContent=`${goal.unlocked} milestones unlocked. Keep growing. `;if(data.phase===2){$('#workout-title').innerHTML='Keep<br>leveling up.';$('#workout-sub').textContent=`Next goal: ${milestoneText(goal)}.`;}const mon=new Date();mon.setDate(mon.getDate()-((mon.getDay()+6)%7));$('#week').innerHTML=Array.from({length:7},(_,i)=>{const d=new Date(mon);d.setDate(d.getDate()+i);const k=dayKey(d);return `<div class="day ${k===today?'today':''} ${dates.includes(k)?'complete':''}">${['M','T','W','T','F','S','S'][i]}<i>${dates.includes(k)?'✓':k===today?'·':'–'}</i></div>`}).join('');$('#routine-list').innerHTML=[['↟','Wake up your bounce',p.warm,'2 min'],['↻','Find your rhythm',`${p.jump}s jumping · ${p.rest}s rest · ${p.rounds} rounds`,`${p.rounds} min`],['⚑',data.phase===2?'Your next milestone':p.challenge,data.phase===2?milestoneText(goal):p.tip,data.phase===0?'1 min':data.phase===2&&goal.type==='seconds'?`${goal.target}s`:'Untimed']].map(r=>`<div class="routine-row"><span class="step-icon">${r[0]}</span><div><h4>${r[1]}</h4><p>${r[2]}</p></div><span class="time">${r[3]}</span></div>`).join('');$('#phase-cards').innerHTML=phases.map((x,i)=>`<article class="phase-card ${i===data.phase?'selected':''}"><div class="tiny">PHASE ${i+1} · ${x.weeks}</div><h2>${x.name}</h2><p>${x.warm}</p><p><b>${x.rounds} rounds:</b> ${x.jump}s jumping / ${x.rest}s rest</p><p><b>${x.challenge}:</b> ${x.tip}</p><p><b>Milestone:</b> ${x.milestone}</p>${i===2?`<p><b>Keep unlocking:</b> 50 jumps → 50 seconds → 60 jumps → 60 seconds → …<br>Each goal grows by 10, with no final level. Next: ${milestoneText(goal)}.</p>`:''}<button class="secondary" data-phase="${i}">${i===data.phase?'Your current phase ✓':'Choose this phase →'}</button></article>`).join('');$$('[data-phase]').forEach(b=>b.onclick=()=>{data.phase=Number(b.dataset.phase);persist();render();toast(`Ready for ${phases[data.phase].name}`)});$('#stats').innerHTML=`<div><strong>${data.sessions.length}</strong>workouts completed</div><div><strong>${b}</strong>personal best jumps</div><div><strong>${streak()}</strong>workout streak</div>`;$('#history').innerHTML=data.sessions.length?[...data.sessions].reverse().map(s=>`<div class="history-row"><div><b>${dateOf(s.date).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}</b><small>${phases[s.phase].name}${s.comfortable?' · Smooth intervals ✓':''}</small></div><b>${s.jumps} jumps${s.seconds?` · ${s.seconds}s`:''} ✦</b></div>`).join(''):'<div class="empty">Your story starts with one session.<br><br>Pick up your rope. Your first win is waiting.</div>';renderProgressCharts(data.sessions)}
let jumpedSeconds=0,stepMark=null;
function accountJumpTime(end=Date.now()){if(stepMark!==null&&!paused&&steps[step]?.title==='Let’s jump!')jumpedSeconds+=Math.max(0,Math.min(end,deadline)-stepMark)/1000;stepMark=end;}
let sessionGoal=null,timeStarted=null,timedSeconds=0,timeTicker=null;
function stopTiming(){if(timeStarted!==null){timedSeconds=Math.floor((performance.now()-timeStarted)/1000);jumpedSeconds+=timedSeconds;timeStarted=null;}clearInterval(timeTicker);timeTicker=null;$('#stopwatch').textContent=`${timedSeconds} seconds`;$('#time-toggle').textContent='Start jumping';}
$('#time-toggle').onclick=()=>{if(timeStarted!==null){stopTiming();return}timedSeconds=0;timeStarted=performance.now();$('#time-toggle').textContent='Stop jumping';timeTicker=setInterval(()=>{$('#stopwatch').textContent=`${Math.floor((performance.now()-timeStarted)/1000)} seconds`;},200);};
$('#time-reset').onclick=()=>{stopTiming();timedSeconds=0;$('#stopwatch').textContent='0 seconds';};
let steps=[],step=0,remaining=0,deadline=0,paused=false,ticker=null,sessionPhase=0,started=0,activeTime=0;
function chime(){if(!data.sound)return;try{const c=new (window.AudioContext||window.webkitAudioContext)(),o=c.createOscillator(),g=c.createGain();o.connect(g);g.connect(c.destination);o.frequency.value=660;g.gain.setValueAtTime(.12,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+.3);o.start();o.stop(c.currentTime+.3);setTimeout(()=>c.close(),500)}catch{}}
function paintTimer(){const s=steps[step];$('#step-counter').textContent=s.kind==='round'?`ROUND ${s.round} OF ${phases[sessionPhase].rounds}`:'WARM-UP';$('#step-title').textContent=s.title;$('#step-tip').textContent=s.tip;$('#timer').textContent=`${String(Math.floor(remaining/60)).padStart(2,'0')}:${String(remaining%60).padStart(2,'0')}`;$('#timer-label').textContent=paused?'TAKE YOUR TIME':s.title==='Catch your breath'?'REST IS PART OF PROGRESS':'FIND YOUR RHYTHM';$('#session-position').textContent=`Step ${step+1} of ${steps.length} · ${s.kind==='round'?'A trip is just a reset. Keep going.':'Easy and gentle to start.'}`;$('#pause').textContent=paused?'Resume':'Pause'}function tick(){if(paused)return;remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));if(remaining===0){advance(false);return}paintTimer()}function loadStep(){stepMark=Date.now();remaining=steps[step].seconds;deadline=Date.now()+remaining*1000;paused=false;paintTimer()}function challenge(){document.querySelector('#challenge-countdown')?.remove();clearInterval(ticker);ticker=null;$('#timer-screen').hidden=true;$('#finish-screen').hidden=false;$('#finish-screen h2').textContent=phases[sessionPhase].challenge;$('#finish-screen p').textContent=phases[sessionPhase].tip+(sessionPhase===1?` Your target: ${best()+1} jumps.`:'');$('#comfortable').parentElement.hidden=sessionPhase!==1;$('#jump-input').value=0;$('#comfortable').checked=false;$('#jump-input').focus();stopTiming();timedSeconds=0;$('#stopwatch').textContent='0 seconds';$('#timed-challenge').hidden=!(sessionPhase===2&&sessionGoal.type==='seconds');if(sessionPhase===2){$('#finish-screen h2').textContent='Your next milestone';$('#finish-screen p').textContent=`Goal: ${milestoneText(sessionGoal)}. ${sessionGoal.type==='seconds'?'Use the stopwatch below to record one continuous attempt.':'Enter your longest unbroken set below.'}`;}if(sessionPhase===0){const note=document.createElement('p');note.id='challenge-countdown';$('#jump-input').before(note);const end=Date.now()+60000;ticker=setInterval(()=>{const left=Math.max(0,Math.ceil((end-Date.now())/1000));note.textContent=left?`${left} seconds · One attempt. Take your time.`:'Time’s up! Record your best attempt below.';if(!left){clearInterval(ticker);ticker=null;chime()}},200)}}
function advance(manual=true){accountJumpTime();chime();if(manual){step++;if(step>=steps.length){challenge();return}loadStep()}else{let nextDeadline=deadline;step++;while(step<steps.length&&nextDeadline+steps[step].seconds*1000<=Date.now()){if(steps[step].title==='Let’s jump!')jumpedSeconds+=steps[step].seconds;nextDeadline+=steps[step].seconds*1000;step++}if(step>=steps.length){challenge();return}stepMark=nextDeadline;deadline=nextDeadline+steps[step].seconds*1000;remaining=Math.ceil((deadline-Date.now())/1000);paintTimer()}}
$('#start').onclick=()=>{jumpedSeconds=0;stepMark=null;sessionPhase=data.phase;sessionGoal=nextMilestone(data.sessions);const p=phases[sessionPhase];steps=p.warmSteps.map(x=>({title:x[0],tip:x[1],seconds:x[2],kind:'warm'}));for(let i=1;i<=p.rounds;i++){steps.push({title:'Let’s jump!',tip:'Aim for a smooth rhythm. If you trip, reset and jump again.',seconds:p.jump,kind:'round',round:i});steps.push({title:'Catch your breath',tip:'Relax your shoulders. Shake it out. You’re doing great.',seconds:p.rest,kind:'round',round:i})}step=0;started=Date.now();$('#session-phase').textContent=`PHASE ${sessionPhase+1} · ${p.name}`;$('#timer-screen').hidden=false;$('#finish-screen').hidden=true;$('#celebration').hidden=true;$('#session').showModal();loadStep();ticker=setInterval(tick,200)};$('#pause').onclick=()=>{if(!paused){accountJumpTime();remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));paused=true}else{deadline=Date.now()+remaining*1000;stepMark=Date.now();paused=false}paintTimer()};$('#skip').onclick=()=>advance();function closeSession(){stopTiming();if(ticker){clearInterval(ticker);ticker=null}$('#session').close()}$('#close-session').onclick=()=>{if(!$('#celebration').hidden||confirm('Leave this workout? It won’t be recorded.'))closeSession()};$('#session').addEventListener('cancel',e=>{e.preventDefault();$('#close-session').click()});$('#finish-screen').onsubmit=e=>{e.preventDefault();clearInterval(ticker);ticker=null;const jumps=Number($('#jump-input').value);if(!Number.isSafeInteger(jumps)||jumps<0)return;stopTiming();const old=best(),previousGoal=nextMilestone(data.sessions);data.sessions.push({date:dayKey(),phase:sessionPhase,jumps,jumpedSeconds:Math.floor(jumpedSeconds),seconds:sessionPhase===2&&sessionGoal.type==='seconds'?timedSeconds:0,comfortable:sessionPhase===1&&$('#comfortable').checked,at:new Date().toISOString()});persist();render();const unlocked=nextMilestone(data.sessions).unlocked>previousGoal.unlocked;$('#finish-screen').hidden=true;$('#celebration').hidden=false;$('#win-copy').textContent=(data.name?`${data.name}, `:'')+(jumps>old?`a new personal best: ${jumps} consecutive jumps! `:'Every time you show up, you grow. ')+(unlocked?`Milestone unlocked! Next up: ${milestoneText(nextMilestone(data.sessions))}.`:'Rest up. Keep your every-other-day rhythm.');confetti()};$('#done').onclick=closeSession;function confetti(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;for(let i=0;i<45;i++){const n=document.createElement('i');n.className='confetti';n.style.left=Math.random()*100+'vw';n.style.background=['#b6d981','#f0b071','#234d37','#e8d76f'][i%4];n.style.animationDelay=Math.random()*.6+'s';document.body.append(n);setTimeout(()=>n.remove(),3500)}}$('#settings').onclick=()=>{$('#name').value=data.name;$('#sound').checked=data.sound;$('#profile').showModal()};$('#close-profile').onclick=()=>$('#profile').close();$('#profile-form').onsubmit=e=>{e.preventDefault();const previous={...data};data.name=$('#name').value.trim();data.sound=$('#sound').checked;if(!persist()){data=previous;return;}render();$('#profile').close();toast('All set. Make it your own pace.')};$('#export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`jump-club-${data.name.replace(/[^a-z0-9_-]/gi,'-')}-progress.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('#import').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;const d=JSON.parse(await f.text());if(!Number.isInteger(d.phase)||d.phase<0||d.phase>2||!Array.isArray(d.sessions)||!d.sessions.every(s=>/^\d{4}-\d{2}-\d{2}$/.test(s.date)&&!isNaN(dateOf(s.date))&&Number.isInteger(s.phase)&&s.phase>=0&&s.phase<3&&Number.isSafeInteger(s.jumps)&&s.jumps>=0&&(s.seconds===undefined||(Number.isSafeInteger(s.seconds)&&s.seconds>=0))&&(s.jumpedSeconds===undefined||(Number.isSafeInteger(s.jumpedSeconds)&&s.jumpedSeconds>=0))))throw Error();if(!confirm(`Replace progress for ${data.name} with ${d.sessions.length} imported workouts? Other jumpers will be unchanged.`))return;data={phase:d.phase,name:data.name,sound:!!d.sound,sessions:d.sessions};persist();render();toast('Your progress is back. Welcome home.')}catch{toast('That backup could not be read. Choose a Jump Club export.')}e.target.value=''};render();
